INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 14, 'theory', 'Quiz: common table expressions');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 14, 0, 'How is a common table expression written?', '["WITH name AS (SELECT …) SELECT … FROM name", "CREATE TABLE name AS …", "SELECT … AS WITH name", "TEMP name (SELECT …)"]', 0, 'Before the main query you write WITH, a name, AS and a SELECT in parentheses; then you refer to the name as to a table.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 14, 1, 'What is the advantage of a CTE over a subquery in FROM?', '["A CTE is always faster", "Readability and the ability to reference the result several times", "A CTE saves data permanently", "A CTE can be used without a SELECT"]', 1, 'A CTE gets a name, reads from top to bottom and can be used many times in a query. Speed does not change by itself.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 14, 2, 'What parts does a recursive CTE consist of?', '["Just a SELECT", "A starting part and a recursive part joined by UNION ALL", "Two independent queries with a JOIN", "A FOR loop"]', 1, 'The starting part gives the first rows, the recursive part produces the next ones from those already obtained; they are joined with UNION [ALL].');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 14, 3, 'What happens with a recursion that has no stop condition on data containing a cycle?', '["The query returns an empty result", "The recursion does not finish (until a limit or a timeout)", "The database cuts the loop itself on the second iteration", "The query raises a syntax error"]', 1, 'Protection is needed: a depth condition, UNION instead of UNION ALL, or a check of the path already traveled.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 14, 4, 'What is a recursive CTE used for in queries?', '["To speed up queries", "To generate series and to walk hierarchies", "To create indexes", "To write data to a table"]', 1, 'Recursion builds series of numbers and dates and walks trees: employees, categories, folders.');
